-- Generated by scripts/generate-career-seed-sql.ts from src/data/careers/*.ts.
-- Do NOT hand-edit this file — edit the TypeScript seed data and re-run:
--   npm run validate:careers   (fails loudly on any bad/unknown key)
--   npm run seed:generate      (regenerates this file)
--
-- HOW TO RUN THIS (no SQL knowledge required):
--   1. First run supabase/migrations/0003_career_database.sql (once) if
--      you haven't already — this seed file assumes those tables exist.
--   2. Open your Supabase project dashboard (supabase.com/dashboard).
--   3. Click "SQL Editor" in the left sidebar, then "New query".
--   4. Paste the entire contents of this file.
--   5. Click "Run".
--
-- Safe to run more than once — every statement below is an upsert or a
-- delete-then-insert keyed off a stable business key (family_key,
-- industry_key, tag_key, career_key), never a raw INSERT. Re-running this
-- file after editing the TypeScript seed data updates existing rows in
-- place instead of creating duplicates.
-- ============================================================================

