insert into public.careers (
  career_key, family_id, title, short_title, slug, summary, what_you_do,
  typical_environment, career_outlook_summary, typical_entry_level, minimum_education_key,
  international_mobility_score, remote_work_score, entrepreneurship_score, salary_potential_score,
  job_security_score, creativity_score, social_impact_score, leadership_opportunity_score,
  travel_score, research_intensity_score, technical_depth_score,
  is_active, is_featured, data_quality_status
)
select
  v.career_key, f.id, v.title, v.short_title, v.slug, v.summary, v.what_you_do,
  v.typical_environment, v.career_outlook_summary, v.typical_entry_level, v.minimum_education_key,
  v.international_mobility_score, v.remote_work_score, v.entrepreneurship_score, v.salary_potential_score,
  v.job_security_score, v.creativity_score, v.social_impact_score, v.leadership_opportunity_score,
  v.travel_score, v.research_intensity_score, v.technical_depth_score,
  true, v.is_featured, v.data_quality_status
from (values
  ($seed$mechanical_engineer$seed$, $seed$engineering$seed$, $seed$Mechanical Engineer$seed$, null, $seed$mechanical-engineer$seed$, $seed$Designs, analyzes, and tests mechanical systems and components, from engines and machines to consumer products and industrial equipment.$seed$, $seed$Works through the design cycle of mechanical parts and systems - sketching concepts, building CAD models, and running stress and thermal simulations before validating prototypes through physical testing. Collaborates with manufacturing, electrical, and quality teams to move a design from concept to a producible product, and troubleshoots mechanical failures found in the field or on the production line.$seed$, $seed$Primarily office-based design and simulation work using CAD and analysis software, with regular time in workshops, test labs, or on factory floors to build and validate prototypes.$seed$, null, $seed$Entry-level design or graduate engineer in a manufacturing, automotive, industrial equipment, or engineering services company$seed$, $seed$bachelors$seed$, 4, 2, 3, 3, 4, 3, 3, 3, 2, 2, 4, true, $seed$approved$seed$),
  ($seed$electrical_engineer$seed$, $seed$engineering$seed$, $seed$Electrical Engineer$seed$, null, $seed$electrical-engineer$seed$, $seed$Designs and develops electrical systems and equipment, from power distribution networks to circuits inside consumer and industrial devices.$seed$, $seed$Designs electrical circuits, power systems, and equipment, working out wiring layouts, load calculations, and protection schemes. Uses simulation and design software to model circuits before building and testing prototypes, and applies relevant electrical safety and regulatory standards throughout the design process.$seed$, $seed$A mix of office-based design work and on-site work at installations, substations, or manufacturing facilities, often within multidisciplinary engineering teams.$seed$, null, $seed$Entry-level or graduate electrical engineer in a power utility, manufacturing, construction, or engineering consultancy firm$seed$, $seed$bachelors$seed$, 4, 2, 2, 3, 4, 2, 3, 3, 2, 2, 4, false, $seed$approved$seed$),
  ($seed$electronics_engineer$seed$, $seed$engineering$seed$, $seed$Electronics Engineer$seed$, null, $seed$electronics-engineer$seed$, $seed$Designs circuits, embedded hardware, and electronic devices, working at the level of chips, boards, and signal processing rather than large power systems.$seed$, $seed$Designs and debugs analog and digital circuits, lays out printed circuit boards, and writes low-level firmware to bring hardware to life. Uses lab instruments such as oscilloscopes and signal generators to test designs, and works closely with embedded software engineers to get hardware and firmware working together.$seed$, $seed$Lab-based and office-based work in roughly equal measure, with bench testing of prototypes alongside CAD/EDA design work, usually in small hardware-focused teams.$seed$, null, $seed$Entry-level hardware or embedded electronics engineer at a consumer electronics, semiconductor, telecom, or product design company$seed$, $seed$bachelors$seed$, 4, 3, 4, 4, 3, 4, 2, 2, 1, 3, 5, false, $seed$approved$seed$),
  ($seed$civil_engineer$seed$, $seed$engineering$seed$, $seed$Civil Engineer$seed$, null, $seed$civil-engineer$seed$, $seed$Plans, designs, and oversees construction of infrastructure such as buildings, roads, bridges, and water systems.$seed$, $seed$Prepares structural designs and drawings, calculates loads and material requirements, and coordinates with architects, contractors, and regulatory bodies. Spends time on construction sites monitoring progress and quality, in addition to office-based design and documentation work.$seed$, $seed$Split between office design work and active construction sites, often outdoors and involving coordination across large project teams and contractors.$seed$, null, $seed$Site engineer or graduate design engineer at a construction firm, infrastructure developer, or government public works department$seed$, $seed$bachelors$seed$, 3, 1, 3, 3, 4, 2, 4, 4, 2, 1, 3, false, $seed$approved$seed$),
  ($seed$chemical_engineer$seed$, $seed$engineering$seed$, $seed$Chemical Engineer$seed$, null, $seed$chemical-engineer$seed$, $seed$Designs and operates processes that convert raw materials into chemicals, fuels, pharmaceuticals, and other products at industrial scale.$seed$, $seed$Designs and troubleshoots chemical processes and plant equipment, models reactions and material flows, and works on scaling up processes from lab batches to full production. Monitors plant operations, manages safety and environmental compliance, and drives projects to improve process efficiency and yield.$seed$, $seed$A mix of process plants, refineries, or manufacturing facilities and office-based process modelling work, often with shift or on-call responsibilities tied to plant operations.$seed$, null, $seed$Process engineer trainee at a chemical plant, refinery, pharmaceutical manufacturer, or specialty materials company$seed$, $seed$bachelors$seed$, 3, 1, 2, 4, 4, 2, 3, 3, 2, 3, 4, false, $seed$approved$seed$),
  ($seed$industrial_engineer$seed$, $seed$engineering$seed$, $seed$Industrial Engineer$seed$, null, $seed$industrial-engineer$seed$, $seed$Improves the efficiency of production systems, workflows, and organizations by analyzing processes, resources, and layouts.$seed$, $seed$Studies how work, materials, and people move through a factory or process, then redesigns layouts, schedules, and workflows to cut waste and improve throughput. Uses data analysis and simulation to compare options, and works with operations and quality teams to implement changes on the ground.$seed$, $seed$Time split between factory floors and offices, analyzing process data, running simulations, and presenting improvement plans to operations managers.$seed$, null, $seed$Process improvement or industrial engineer trainee at a manufacturing company, logistics operator, or consulting firm$seed$, $seed$bachelors$seed$, 3, 2, 3, 3, 3, 3, 2, 4, 2, 2, 3, false, $seed$approved$seed$),
  ($seed$mechatronics_engineer$seed$, $seed$engineering$seed$, $seed$Mechatronics Engineer$seed$, null, $seed$mechatronics-engineer$seed$, $seed$Combines mechanical, electrical, and software engineering to design integrated systems such as automated machines and smart products.$seed$, $seed$Designs systems that combine mechanical parts, sensors, actuators, and embedded control software, and integrates them so they work together reliably. Builds and tests prototypes of automated equipment, and debugs issues that span mechanical, electrical, and software layers.$seed$, $seed$Lab and workshop-based prototyping combined with office-based design and coding, typically within small cross-disciplinary product or automation teams.$seed$, null, $seed$Graduate mechatronics or systems engineer at an automation, robotics, consumer electronics, or industrial equipment company$seed$, $seed$bachelors$seed$, 4, 2, 4, 4, 3, 4, 2, 2, 2, 3, 5, false, $seed$approved$seed$),
  ($seed$robotics_engineer$seed$, $seed$engineering$seed$, $seed$Robotics Engineer$seed$, null, $seed$robotics-engineer$seed$, $seed$Designs, builds, and programs robots and autonomous systems for use in manufacturing, logistics, healthcare, and other fields.$seed$, $seed$Develops the mechanical design, sensors, and control software that let robots perceive their environment and perform tasks autonomously or semi-autonomously. Tests robots in simulation and on physical hardware, and works to make systems reliable, safe, and repeatable at scale.$seed$, $seed$Lab and workshop-based robot testing alongside heavy software and simulation work at a desk, usually in fast-moving, small technical teams.$seed$, null, $seed$Graduate robotics engineer at a robotics startup, automation integrator, or R&D lab within a larger manufacturing or technology company$seed$, $seed$bachelors$seed$, 4, 2, 4, 4, 3, 4, 3, 2, 2, 4, 5, true, $seed$approved$seed$),
  ($seed$controls_engineer$seed$, $seed$engineering$seed$, $seed$Controls Engineer$seed$, null, $seed$controls-engineer$seed$, $seed$Designs and maintains the control systems and automation logic that keep machines, processes, and plants running accurately and safely.$seed$, $seed$Designs control loops, PLC programs, and instrumentation schemes that regulate equipment such as motors, valves, and production lines. Commissions and tunes control systems on site, and troubleshoots faults that affect process stability or product quality.$seed$, $seed$Time divided between control-room and office-based programming work and hands-on commissioning on factory floors or process plants.$seed$, null, $seed$Graduate controls or automation engineer at a manufacturing plant, process industry operator, or automation systems integrator$seed$, $seed$bachelors$seed$, 3, 2, 2, 3, 4, 2, 2, 2, 3, 2, 4, false, $seed$approved$seed$),
  ($seed$manufacturing_engineer$seed$, $seed$engineering$seed$, $seed$Manufacturing Engineer$seed$, null, $seed$manufacturing-engineer$seed$, $seed$Designs and improves the processes, tooling, and production lines used to manufacture products efficiently and consistently.$seed$, $seed$Plans production processes, selects and designs tooling and fixtures, and works out the sequence of operations needed to build a product at scale. Spends time on the shop floor resolving production issues, and drives continuous improvement projects to raise yield and reduce cost.$seed$, $seed$Primarily on the factory floor working directly with production teams and equipment, with supporting office time for planning and documentation.$seed$, null, $seed$Graduate manufacturing or process engineer at a factory, automotive plant, or contract manufacturer$seed$, $seed$bachelors$seed$, 2, 1, 2, 3, 4, 2, 2, 3, 2, 1, 3, false, $seed$approved$seed$),
  ($seed$quality_engineer$seed$, $seed$engineering$seed$, $seed$Quality Engineer$seed$, null, $seed$quality-engineer$seed$, $seed$Ensures products and processes consistently meet defined quality standards through inspection, testing, and root-cause problem solving.$seed$, $seed$Sets up inspection and testing procedures, analyzes defect and process data to find the root causes of quality problems, and works with design and production teams to fix them. Maintains quality documentation and compliance records, and audits suppliers or production processes against required standards.$seed$, $seed$A mix of factory floor inspection work, lab-based testing, and office-based data analysis and documentation, usually within a quality or compliance department.$seed$, null, $seed$Graduate quality engineer or quality assurance associate at a manufacturing, automotive, medical device, or electronics company$seed$, $seed$bachelors$seed$, 2, 2, 1, 2, 4, 1, 3, 2, 2, 2, 3, false, $seed$approved$seed$),
  ($seed$reliability_engineer$seed$, $seed$engineering$seed$, $seed$Reliability Engineer$seed$, null, $seed$reliability-engineer$seed$, $seed$Analyzes equipment and system failures to improve reliability, reduce downtime, and plan maintenance strategies for industrial assets.$seed$, $seed$Studies failure data and maintenance history to identify why equipment breaks down, and designs preventive and predictive maintenance plans to reduce unplanned downtime. Works with operations and maintenance teams to investigate failures, and models the expected lifespan and risk of critical equipment.$seed$, $seed$A mix of plant or field visits to inspect equipment and office-based data analysis and reporting, typically within maintenance or asset management functions.$seed$, null, $seed$Graduate reliability or maintenance engineer at a manufacturing plant, power utility, oil and gas facility, or heavy industry operator$seed$, $seed$bachelors$seed$, 2, 2, 1, 3, 4, 1, 2, 2, 2, 3, 4, false, $seed$approved$seed$),
  ($seed$automotive_engineer$seed$, $seed$automotive_mobility$seed$, $seed$Automotive Engineer$seed$, null, $seed$automotive-engineer$seed$, $seed$Designs, tests, and improves vehicles and their subsystems, from chassis and engine to safety and comfort features.$seed$, $seed$Works across the vehicle development process — concept design, prototyping, testing, and validation of components such as engines, transmissions, chassis, and body structures. Uses CAD tools and physical testing to refine performance, cost, and manufacturability, coordinating with suppliers and manufacturing teams.$seed$, $seed$Primarily office and lab-based design and testing work, with periodic time on the shop floor or at test tracks, within a larger vehicle engineering team.$seed$, null, $seed$Entry-level graduate engineer at an automotive OEM or components supplier$seed$, $seed$bachelors$seed$, 3, 2, 2, 3, 4, 3, 2, 3, 2, 2, 4, false, $seed$approved$seed$),
  ($seed$ev_systems_engineer$seed$, $seed$automotive_mobility$seed$, $seed$EV Systems Engineer$seed$, null, $seed$ev-systems-engineer$seed$, $seed$Works on the electrical and control systems — battery management, motor drives, charging — that make electric vehicles function.$seed$, $seed$Designs and integrates high-voltage electrical architecture, motor control software, and charging interfaces for electric vehicles. Runs bench and vehicle-level tests to validate performance, thermal behavior, and safety, working closely with battery, software, and mechanical teams.$seed$, $seed$Split between electronics labs, vehicle test bays, and office-based simulation work, inside a cross-functional EV engineering team.$seed$, null, $seed$Entry-level graduate engineer at an EV manufacturer, automotive supplier, or mobility startup$seed$, $seed$bachelors$seed$, 4, 2, 3, 4, 4, 3, 4, 3, 2, 3, 5, true, $seed$approved$seed$),
  ($seed$battery_engineer$seed$, $seed$automotive_mobility$seed$, $seed$Battery Engineer$seed$, null, $seed$battery-engineer$seed$, $seed$Develops and tests battery cells, packs, and management systems used in electric vehicles and energy storage.$seed$, $seed$Works on cell chemistry selection, pack design, thermal management, and battery management system (BMS) logic. Runs abuse and life-cycle testing, analyzes failure modes, and works with manufacturing teams to scale production safely.$seed$, $seed$Laboratory and testing-facility work combined with office-based data analysis and design, often within a battery or energy-storage division of an automotive or energy company.$seed$, null, $seed$Entry-level graduate engineer at a battery manufacturer, EV OEM, or energy storage company$seed$, $seed$bachelors$seed$, 3, 1, 2, 4, 4, 2, 4, 2, 1, 5, 5, false, $seed$approved$seed$),
  ($seed$vehicle_dynamics_engineer$seed$, $seed$automotive_mobility$seed$, $seed$Vehicle Dynamics Engineer$seed$, null, $seed$vehicle-dynamics-engineer$seed$, $seed$Studies and tunes how a vehicle handles, rides, and responds to steering, braking, and road conditions.$seed$, $seed$Analyzes suspension geometry, tire behavior, and vehicle handling using simulation models and physical test-track data. Tunes suspension, steering, and stability-control settings, and works with prototype vehicles to validate ride and handling targets.$seed$, $seed$A mix of simulation work in the office, physical testing at proving grounds and test tracks, and collaboration with chassis and controls teams.$seed$, null, $seed$Graduate engineer role in a vehicle dynamics or chassis team at an automotive OEM or motorsport outfit$seed$, $seed$bachelors$seed$, 3, 1, 1, 3, 3, 3, 2, 2, 3, 3, 5, false, $seed$approved$seed$),
  ($seed$automotive_cae_engineer$seed$, $seed$automotive_mobility$seed$, $seed$Automotive CAE Engineer$seed$, null, $seed$automotive-cae-engineer$seed$, $seed$Uses computer simulation of crashes, structures, thermal and airflow behavior to predict and improve vehicle performance before physical prototypes are built.$seed$, $seed$Builds finite-element and CFD models to simulate crash safety, structural loads, NVH, and thermal behavior of vehicle components. Interprets simulation results, recommends design changes, and correlates simulation output against physical test data.$seed$, $seed$Almost entirely office and desk-based simulation work, with occasional visits to test labs to validate models against physical results.$seed$, null, $seed$Entry-level CAE or simulation engineer at an automotive OEM or supplier$seed$, $seed$bachelors$seed$, 3, 4, 1, 3, 4, 2, 2, 2, 1, 4, 5, false, $seed$approved$seed$),
  ($seed$powertrain_engineer$seed$, $seed$automotive_mobility$seed$, $seed$Powertrain Engineer$seed$, null, $seed$powertrain-engineer$seed$, $seed$Designs and develops engines, transmissions, and hybrid or electric drive systems that move a vehicle.$seed$, $seed$Works on the design, calibration, and testing of internal combustion, hybrid, or electric powertrains, balancing performance, emissions, efficiency, and durability. Runs dyno testing and works with control-software teams to calibrate engine and transmission behavior.$seed$, $seed$A combination of test-cell and dyno lab work, workshop time with prototype hardware, and office-based design and calibration work.$seed$, null, $seed$Entry-level graduate engineer in a powertrain or propulsion team at an automotive OEM or supplier$seed$, $seed$bachelors$seed$, 3, 1, 1, 3, 3, 2, 2, 2, 2, 3, 5, false, $seed$approved$seed$),
  ($seed$autonomous_vehicle_engineer$seed$, $seed$automotive_mobility$seed$, $seed$Autonomous Vehicle Engineer$seed$, null, $seed$autonomous-vehicle-engineer$seed$, $seed$Builds the perception, planning, and control software that lets vehicles sense their surroundings and drive with reduced or no human input.$seed$, $seed$Develops and tests algorithms for sensor fusion, object detection, path planning, and vehicle control using camera, lidar, and radar data. Works with large driving datasets, runs simulation testing, and validates behavior on closed test tracks or instrumented vehicles.$seed$, $seed$Primarily software development and data work in an office or lab setting, with periodic on-road or test-track validation sessions.$seed$, null, $seed$Entry-level software or robotics engineer at an autonomous driving company, automotive OEM, or robotics lab$seed$, $seed$bachelors$seed$, 4, 3, 3, 5, 3, 4, 3, 2, 2, 5, 5, false, $seed$approved$seed$),
  ($seed$marine_engineer$seed$, $seed$marine_maritime$seed$, $seed$Marine Engineer$seed$, null, $seed$marine-engineer$seed$, $seed$Designs, operates, and maintains the propulsion, power, and mechanical systems that keep ships running.$seed$, $seed$Works on engines, generators, pumps, and auxiliary machinery aboard ships or in shore-based design roles. Performs maintenance planning, troubleshoots mechanical and electrical faults, and ensures systems meet safety and efficiency standards.$seed$, $seed$Either onboard a vessel in the engine room on rotational sea postings, or shore-based in a design or technical office, depending on career track; both involve close teamwork with deck and technical crew.$seed$, null, $seed$Cadet or trainee marine engineer progressing through certificated ranks, or graduate engineer in a shore-based marine engineering role$seed$, $seed$bachelors$seed$, 5, 1, 1, 3, 4, 1, 2, 3, 5, 1, 4, false, $seed$approved$seed$),
  ($seed$naval_architect$seed$, $seed$marine_maritime$seed$, $seed$Naval Architect$seed$, null, $seed$naval-architect$seed$, $seed$Designs the hull form, structure, and stability of ships and other marine vessels.$seed$, $seed$Develops hull geometry, structural layout, and stability calculations for new vessels, using naval architecture software and model testing. Works with marine engineers and classification societies to ensure designs meet performance, safety, and regulatory requirements.$seed$, $seed$Mostly office-based design and calculation work, with visits to shipyards or model-testing tanks during design verification and build phases.$seed$, null, $seed$Graduate naval architect at a ship design consultancy, shipyard, or classification society$seed$, $seed$bachelors$seed$, 4, 2, 2, 3, 3, 4, 2, 2, 2, 3, 5, false, $seed$approved$seed$),
  ($seed$ship_design_engineer$seed$, $seed$marine_maritime$seed$, $seed$Ship Design Engineer$seed$, null, $seed$ship-design-engineer$seed$, $seed$Works on the detailed engineering design of ship systems — structure, piping, layout — turning naval architecture concepts into buildable drawings.$seed$, $seed$Produces detailed structural, piping, and general-arrangement drawings for vessels using CAD and 3D modeling tools, working from naval architecture specifications. Coordinates with production teams at the shipyard to resolve design and build issues during construction.$seed$, $seed$Primarily office-based drafting and design work, with periodic shipyard visits to check the design against construction progress.$seed$, null, $seed$Graduate design engineer at a shipyard, ship design consultancy, or marine engineering firm$seed$, $seed$bachelors$seed$, 3, 2, 1, 3, 3, 3, 2, 2, 1, 2, 4, false, $seed$approved$seed$),
