  slug = excluded.slug,
  summary = excluded.summary,
  what_you_do = excluded.what_you_do,
  typical_environment = excluded.typical_environment,
  career_outlook_summary = excluded.career_outlook_summary,
  typical_entry_level = excluded.typical_entry_level,
  minimum_education_key = excluded.minimum_education_key,
  international_mobility_score = excluded.international_mobility_score,
  remote_work_score = excluded.remote_work_score,
  entrepreneurship_score = excluded.entrepreneurship_score,
  salary_potential_score = excluded.salary_potential_score,
  job_security_score = excluded.job_security_score,
  creativity_score = excluded.creativity_score,
  social_impact_score = excluded.social_impact_score,
  leadership_opportunity_score = excluded.leadership_opportunity_score,
  travel_score = excluded.travel_score,
  research_intensity_score = excluded.research_intensity_score,
  technical_depth_score = excluded.technical_depth_score,
  is_active = true,
  is_featured = excluded.is_featured,
  data_quality_status = excluded.data_quality_status,
  updated_at = now();

